import {isFeatureEnabled} from '@github-ui/feature-flags'
import {AlphaLabel} from '@github-ui/lifecycle-labels/alpha'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {ListView} from '@github-ui/list-view'
import {ListError} from '@github-ui/list-view-items-issues-prs/ListError'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {useQueries} from '@github-ui/react-query'
import {useNavigate} from '@github-ui/react-router'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {Link, Stack} from '@primer/react'
import {useCallback, useState} from 'react'
import styles from '../DashboardLists.module.css'
import type {DashboardPullRequest} from '../types'
import {QueryQualifier} from '../types'
import {dashboardLocalStorage} from '../utils/dashboard-local-storage'
import {dedupeById} from '../utils/dedupe-by-id'
import {ListActionMenu} from './ListActionMenu'
import {PullRequestListItem} from './PullRequestListItem'

interface PullRequestsListProps {
  userDisplayLogin: string
  loadingState: () => React.ReactElement
}

const DEFAULT_RESULT_COUNT = 6
const DEFAULT_QUERY_QUALIFIERS = [QueryQualifier.Authored]

export function PullRequestsList({userDisplayLogin, loadingState}: PullRequestsListProps) {
  const navigate = useNavigate()
  const initialQueryQualifiers = dashboardLocalStorage.getPullRequestQueryQualifiers() || DEFAULT_QUERY_QUALIFIERS
  const [queryQualifiers, setQueryQualifiers] = useState<QueryQualifier[]>(initialQueryQualifiers)
  const initialResultCount = dashboardLocalStorage.getPullRequestResultCount() || DEFAULT_RESULT_COUNT
  const [resultCount, setResultCount] = useState<number>(initialResultCount)

  const navigateToPullsIndex = useCallback(() => {
    navigate('/pulls')
  }, [navigate])

  const setPullRequestQueryQualifiers = (queries: QueryQualifier[]) => {
    setQueryQualifiers(queries)
    dashboardLocalStorage.setPullRequestQueryQualifiers(queries)
  }

  const setPullRequestResultCount = (count: number) => {
    setResultCount(count)
    dashboardLocalStorage.setPullRequestResultCount(count)
  }

  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const onViewAllPulls = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.view_all_pulls'})
  }, [sendClickAnalyticsEvent])
  const onTitleClick = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.navigate_to_pr'})
  }, [sendClickAnalyticsEvent])
  const baseQuery = 'is:pr is:open archived:false sort:updated-desc'

  const {
    isLoading,
    data: pullRequests,
    isError,
  } = useQueries({
    queries: queryQualifiers.map(qualifier => ({
      queryKey: [baseQuery, qualifier, userDisplayLogin],
      queryFn: async () => {
        const response = await reactFetchJSON(
          `/productivity_dashboard/pulls?q=${encodeURIComponent(`${baseQuery} ${qualifier}:${userDisplayLogin}`)}`,
        )

        if (!response.ok) throw new Error(`HTTP ${response.status}`)

        const payload = (await response.json()).data as DashboardPullRequest[]
        return payload
      },
    })),
    combine: results => {
      return {
        data: dedupeById(results.flatMap(result => result.data || [])).slice(0, resultCount),
        isLoading: results.some(result => result.isLoading),
        isError: results.some(result => result.isError),
      }
    },
  })

  return (
    <ListView
      aria-busy={isLoading ? true : undefined}
      title="Pull Requests"
      className={styles.List}
      metadata={
        <ListViewMetadata
          className={styles.metadataOverride}
          title={
            <Stack direction="horizontal" gap="condensed" align="center">
              <Link className={styles.titleLink} href="/pulls" onClick={onViewAllPulls}>
                Pull requests
              </Link>
              {isFeatureEnabled('productivity_dashboard') ? null : isFeatureEnabled('dashboard_public_preview') ? (
                <BetaLabel />
              ) : (
                <AlphaLabel />
              )}
            </Stack>
          }
        >
          <ListActionMenu
            setQueryQualifiers={setPullRequestQueryQualifiers}
            initialQueryQualifiers={queryQualifiers}
            setResultCount={setPullRequestResultCount}
            initialResultCount={resultCount}
            label="Pull request options"
            filterGroupHeading="Pull requests to include"
            menuItems={[
              {label: 'Authored', value: QueryQualifier.Authored},
              {label: 'Mentioned', value: QueryQualifier.Mentions},
              {label: 'Review requested', value: QueryQualifier.ReviewRequested},
              {label: 'Reviewed', value: QueryQualifier.ReviewedBy},
            ]}
            analyticsEventType={'pull_request_options.save'}
            analyticsTarget={'DASHBOARD_PULL_REQUEST_ACTION_MENU'}
          />
        </ListViewMetadata>
      }
    >
      {isError ? (
        <ListError
          title="Something went wrong"
          message="Unable to load pull requests"
          retryText="Visit the pull requests page"
          retry={navigateToPullsIndex}
        />
      ) : isLoading ? (
        loadingState()
      ) : pullRequests.length === 0 ? (
        <ListItem title={<ListItemTitle containerClassName={styles.noItems} value="No pull requests" />} />
      ) : (
        pullRequests.map(pullRequest => (
          <PullRequestListItem key={pullRequest.id} pullRequest={pullRequest} onTitleClick={onTitleClick} />
        ))
      )}
    </ListView>
  )
}

try{ PullRequestsList.displayName ||= 'PullRequestsList' } catch {}