import type {RepositoryNWO} from '@github-ui/current-repository'

export type DashboardIssue = {
  author: string
  id: string
  title: string
  number: number
  permalink: string
  commentCount: number
  updatedAt: string
  repoNameWithOwner: RepositoryNWO
  readByCurrentUser: boolean
}

export type DashboardPullRequest = {
  author: string
  id: string
  title: string
  number: number
  permalink: string
  commentCount: number
  updatedAt: string
  suggestedAction: string
  headSha: string
  repoNameWithOwner: RepositoryNWO
  isDraft: boolean
  inMergeQueue: boolean
  readByCurrentUser: boolean
}

export const QueryQualifier = {
  Authored: 'author',
  Mentions: 'mentions',
  ReviewRequested: 'review-requested',
  ReviewedBy: 'reviewed-by',
  Assigned: 'assignee',
  Involves: 'involves',
} as const

export type MenuItem = {
  label: string
  value: QueryQualifier
}

export type QueryQualifier = (typeof QueryQualifier)[keyof typeof QueryQualifier]
