import {SkeletonText} from '@primer/react/experimental'
import {IssuesList} from './components/IssuesList'
import {PullRequestsList} from './components/PullRequestsList'
import {AgentsList} from './components/AgentsList'
import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'

export interface DashboardListsProps {
  userDisplayLogin: string
  showProductivityDashboardModules: boolean
  showAgentsModule?: boolean
}

const loadingState = () => (
  <>
    <div className="p-2 border-bottom border-gray-200">
      <SkeletonText lines={2} />
    </div>
    <div className="p-2 border-bottom border-gray-200">
      <SkeletonText lines={2} />
    </div>
    <div className="p-2">
      <SkeletonText lines={2} />
    </div>
  </>
)

export function DashboardLists({
  userDisplayLogin,
  showProductivityDashboardModules,
  showAgentsModule = false,
}: DashboardListsProps) {
  return (
    <>
      {showAgentsModule ? (
        <ConsecutiveCAPI401sProvider>
          <AgentsList loadingState={loadingState} />
        </ConsecutiveCAPI401sProvider>
      ) : null}

      <PullRequestsList userDisplayLogin={userDisplayLogin} loadingState={loadingState} />

      {showProductivityDashboardModules ? (
        <IssuesList userDisplayLogin={userDisplayLogin} loadingState={loadingState} />
      ) : null}
    </>
  )
}

try{ DashboardLists.displayName ||= 'DashboardLists' } catch {}