import {ListView} from '@github-ui/list-view'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {useNavigate} from '@github-ui/react-router'
import {Link, Stack} from '@primer/react'
import {useCallback} from 'react'
import styles from '../DashboardLists.module.css'
import {useTasks} from '@github-ui/agent-sessions/hooks/useTasks'

interface AgentsListProps {
  loadingState: () => React.ReactElement
}

export function AgentsList({loadingState}: AgentsListProps) {
  const navigate = useNavigate()
  const navigateToAgentsIndex = useCallback(() => {
    navigate('/copilot/agents')
  }, [navigate])

  // Fetch tasks for the current user
  const {tasks, isLoading, isError} = useTasks({sessionsPollingInterval: 10000})

  return (
    <ListView
      aria-busy={isLoading ? true : undefined}
      title="Agent tasks"
      className={styles.List}
      metadata={
        <ListViewMetadata
          className={styles.metadataOverride}
          title={
            <Stack direction="horizontal" gap="condensed" align="center">
              <Link className={styles.titleLink} href="/copilot/agents" onClick={navigateToAgentsIndex}>
                Agent tasks
              </Link>
            </Stack>
          }
        />
      }
    >
      {isError ? (
        <ListItem title={<ListItemTitle containerClassName={styles.noItems} value="Unable to load agents" />} />
      ) : isLoading ? (
        loadingState()
      ) : tasks.length === 0 ? (
        <ListItem title={<ListItemTitle containerClassName={styles.noItems} value="No agents" />} />
      ) : (
        tasks.map((task, index) => {
          const key = task.pull?.id ?? index
          const title = task.pull?.title ?? `Agent task ${index + 1}`
          return <ListItem key={key} title={<ListItemTitle value={title} />} />
        })
      )}
    </ListView>
  )
}

try{ AgentsList.displayName ||= 'AgentsList' } catch {}