import {ListItem} from '@github-ui/list-view/ListItem'
import type {DashboardIssue} from '../types'
import {getIssueStateIcon} from '@github-ui/list-view-items-issues-prs/StateIcon'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {CommentIcon} from '@primer/octicons-react'
import {RelativeTime} from '@primer/react'
import styles from '../DashboardLists.module.css'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'

interface IssueListItemProps {
  issue: DashboardIssue
  onTitleClick: () => void
}

export function IssueListItem({issue, onTitleClick}: IssueListItemProps) {
  const repoNameWithOwner = `${issue.repoNameWithOwner.ownerLogin}/${issue.repoNameWithOwner.name}`

  return (
    <ListItem
      title={
        <ListItemTitle
          headingClassName={styles.titleOverride}
          value={issue.title}
          href={issue.permalink}
          onClick={onTitleClick}
        />
      }
      metadata={
        <>
          {issue.commentCount === 0 && !issue.readByCurrentUser && (
            <ListItemMetadata>
              <div className={styles.activityIndicator} data-testid="activity-indicator" />
              <span className="sr-only">New activity.</span>
            </ListItemMetadata>
          )}
          {issue.commentCount > 0 && (
            <ListItemMetadata>
              <div>
                <div
                  className={!issue.readByCurrentUser ? styles.commentIconWithIndicator : undefined}
                  data-testid={!issue.readByCurrentUser ? 'activity-indicator' : undefined}
                >
                  <CommentIcon size={16} data-testid="comment-icon" /> <span>{issue.commentCount}</span>
                </div>
                <span className="sr-only">{issue.commentCount === 1 ? ' comment' : ' comments'}</span>
                {!issue.readByCurrentUser && <span className="sr-only">New activity.</span>}
              </div>
            </ListItemMetadata>
          )}
          <ListItemMetadata>
            <RelativeTime format="micro" datetime={issue.updatedAt} />
          </ListItemMetadata>
        </>
      }
    >
      <ListItemLeadingContent>
        <ListItemLeadingVisual className={styles.leadingVisualOverride} {...getIssueStateIcon('OPEN')} />
      </ListItemLeadingContent>
      <ListItemMainContent>
        <ListItemDescription>{`${repoNameWithOwner}#${issue.number} · Opened by ${issue.author}`}</ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
}

try{ IssueListItem.displayName ||= 'IssueListItem' } catch {}