import {ListView} from '@github-ui/list-view'
import {ListError} from '@github-ui/list-view-items-issues-prs/ListError'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {useQueries} from '@github-ui/react-query'
import {useNavigate} from '@github-ui/react-router'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {Link, Stack} from '@primer/react'
import {useCallback, useState} from 'react'
import styles from '../DashboardLists.module.css'
import type {DashboardIssue} from '../types'
import {QueryQualifier} from '../types'
import {dashboardLocalStorage} from '../utils/dashboard-local-storage'
import {dedupeById} from '../utils/dedupe-by-id'
import {IssueListItem} from './IssueListItem'
import {ListActionMenu} from './ListActionMenu'

interface IssuesListProps {
  userDisplayLogin: string
  loadingState: () => React.ReactElement
}

const DEFAULT_RESULT_COUNT = 6
const DEFAULT_QUERY_QUALIFIERS = [QueryQualifier.Assigned]

export function IssuesList({userDisplayLogin, loadingState}: IssuesListProps) {
  const navigate = useNavigate()
  const initialQueryQualifiers = dashboardLocalStorage.getIssueQueryQualifiers() || DEFAULT_QUERY_QUALIFIERS
  const [queryQualifiers, setQueryQualifiers] = useState<QueryQualifier[]>(initialQueryQualifiers)
  const initialResultCount = dashboardLocalStorage.getIssueResultCount() || DEFAULT_RESULT_COUNT
  const [resultCount, setResultCount] = useState<number>(initialResultCount)

  const navigateToIssuesIndex = useCallback(() => {
    navigate('/issues')
  }, [navigate])

  const setIssueQueryQualifiers = (queries: QueryQualifier[]) => {
    setQueryQualifiers(queries)
    dashboardLocalStorage.setIssueQueryQualifiers(queries)
  }

  const setIssueResultCount = (count: number) => {
    setResultCount(count)
    dashboardLocalStorage.setIssueResultCount(count)
  }

  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const onViewAllIssues = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.view_all_issues'})
  }, [sendClickAnalyticsEvent])
  const onTitleClick = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.navigate_to_issue'})
  }, [sendClickAnalyticsEvent])

  const baseQuery = 'is:issue is:open archived:false sort:updated-desc'

  const {
    isLoading,
    data: issues,
    isError,
  } = useQueries({
    queries: queryQualifiers.map(qualifier => ({
      queryKey: [baseQuery, qualifier, userDisplayLogin],
      queryFn: async () => {
        const response = await reactFetchJSON(
          `/productivity_dashboard/issues?q=${encodeURIComponent(`${baseQuery} ${qualifier}:${userDisplayLogin}`)}`,
        )

        if (!response.ok) throw new Error(`HTTP ${response.status}`)

        const payload = (await response.json()).data as DashboardIssue[]
        return payload
      },
    })),
    combine: results => {
      return {
        data: dedupeById(results.flatMap(result => result.data || [])).slice(0, resultCount),
        isLoading: results.some(result => result.isLoading),
        isError: results.some(result => result.isError),
      }
    },
  })

  return (
    <ListView
      aria-busy={isLoading ? true : undefined}
      title="Issues"
      className={styles.List}
      metadata={
        <ListViewMetadata
          className={styles.metadataOverride}
          title={
            <Stack direction="horizontal" gap="condensed" align="center">
              <Link className={styles.titleLink} href="/issues" onClick={onViewAllIssues}>
                Issues
              </Link>
            </Stack>
          }
        >
          <ListActionMenu
            setQueryQualifiers={setIssueQueryQualifiers}
            initialQueryQualifiers={queryQualifiers}
            setResultCount={setIssueResultCount}
            initialResultCount={resultCount}
            label="Issue options"
            filterGroupHeading="Issues to include"
            menuItems={[
              {label: 'Assigned to me', value: QueryQualifier.Assigned},
              {label: 'Involves me', value: QueryQualifier.Involves},
            ]}
            analyticsEventType={'issues_options.save'}
            analyticsTarget={'DASHBOARD_ISSUES_ACTION_MENU'}
          />
        </ListViewMetadata>
      }
    >
      {isError ? (
        <ListError
          title="Something went wrong"
          message="Unable to load issues"
          retryText="Visit the issues page"
          retry={navigateToIssuesIndex}
        />
      ) : isLoading ? (
        loadingState()
      ) : issues.length === 0 ? (
        <ListItem title={<ListItemTitle containerClassName={styles.noItems} value="No issues" />} />
      ) : (
        issues.map(issue => <IssueListItem key={issue.id} issue={issue} onTitleClick={onTitleClick} />)
      )}
    </ListView>
  )
}

try{ IssuesList.displayName ||= 'IssuesList' } catch {}