import {useAnalytics} from '@github-ui/use-analytics'
import {GearIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton} from '@primer/react'
import {useState} from 'react'
import styles from '../DashboardLists.module.css'
import type {QueryQualifier, MenuItem} from '../types'

export const RESULT_COUNTS = [3, 6, 9, 12]

export interface ListActionMenuProps {
  setQueryQualifiers: (queries: QueryQualifier[]) => void
  initialQueryQualifiers: QueryQualifier[]
  setResultCount: (count: number) => void
  initialResultCount: number
  menuItems: MenuItem[]
  label: string
  filterGroupHeading: string
  analyticsEventType?: string
  analyticsTarget?: string
}

export function ListActionMenu({
  setQueryQualifiers,
  initialQueryQualifiers,
  setResultCount,
  initialResultCount,
  menuItems,
  label,
  filterGroupHeading,
  analyticsEventType,
  analyticsTarget,
}: ListActionMenuProps) {
  const findIndices = (): Set<number> => {
    return new Set(initialQueryQualifiers.map(qualifier => menuItems.findIndex(item => item.value === qualifier)))
  }
  const isValidMenuItemIndex = (index: number): boolean => index >= 0 && index < menuItems.length
  const getQueryQualifiers = (indices: Set<number>): QueryQualifier[] => {
    return Array.from(indices).reduce<QueryQualifier[]>((acc, selectedIndex) => {
      if (isValidMenuItemIndex(selectedIndex)) {
        const value = menuItems[selectedIndex]?.value
        if (value !== undefined) acc.push(value)
      }
      return acc
    }, [])
  }

  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(() => findIndices())
  const [open, setOpen] = useState<boolean>(false)
  const {sendAnalyticsEvent} = useAnalytics()
  const [selectedResultCount, setSelectedResultCount] = useState<number>(initialResultCount)

  const handleSelect = (index: number): void => {
    const newSelectedIndices = new Set(selectedIndices)
    if (selectedIndices.has(index)) {
      newSelectedIndices.delete(index)
    } else {
      newSelectedIndices.add(index)
    }
    setSelectedIndices(newSelectedIndices)

    const queryQualifiers = getQueryQualifiers(newSelectedIndices)
    setQueryQualifiers(queryQualifiers)
  }

  const handleOpenChange = (isOpen: boolean) => {
    setOpen(isOpen)

    if (!isOpen && analyticsEventType && analyticsTarget) {
      const queryQualifiers = getQueryQualifiers(selectedIndices)
      sendAnalyticsEvent(analyticsEventType, analyticsTarget, {
        filters: queryQualifiers.join(','),
        category: 'productivity_dashboard',
        result_count: selectedResultCount.toString(),
      })
    }
  }

  return (
    <ActionMenu open={open} onOpenChange={handleOpenChange}>
      <ActionMenu.Anchor>
        <IconButton
          icon={GearIcon}
          variant="invisible"
          aria-label={label}
          tooltipDirection="w"
          className={styles.Muted}
          size="small"
          data-testid="action-menu-button"
        />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay width="small" align="end" data-testid="action-menu-overlay">
        <ActionList role="menu">
          <ActionList.Group selectionVariant="multiple">
            <ActionList.GroupHeading>{filterGroupHeading}</ActionList.GroupHeading>
            {menuItems.map((item, index) => (
              <ActionList.Item
                key={item.value}
                role="menuitemcheckbox"
                selected={selectedIndices.has(index)}
                aria-checked={selectedIndices.has(index)}
                onSelect={e => {
                  e.preventDefault() // Prevent ActionMenu from closing on select
                  handleSelect(index)
                }}
              >
                {item.label}
              </ActionList.Item>
            ))}
          </ActionList.Group>
          <ActionList.Divider />

          <ActionList.Group selectionVariant="single">
            <ActionList.GroupHeading>Number of results</ActionList.GroupHeading>
            {RESULT_COUNTS.map(count => (
              <ActionList.Item
                key={count}
                role="menuitemradio"
                selected={selectedResultCount === count}
                aria-checked={selectedResultCount === count}
                onSelect={e => {
                  e.preventDefault() // Prevent ActionMenu from closing on select
                  setSelectedResultCount(count)
                  setResultCount(count)
                }}
              >
                {count}
              </ActionList.Item>
            ))}
          </ActionList.Group>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

try{ ListActionMenu.displayName ||= 'ListActionMenu' } catch {}